int x86emul_sysexit(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;

    // Retrieve the EFER MSR value
    if (ctxt->ops->get_msr(ctxt, MSR_EFER, &efer))
        return X86EMUL_UNHANDLEABLE;

    // Check if in real mode
    if ((efer & EFER_LMA) == 0) {
        return X86EMUL_UNHANDLEABLE;
    }

    // Get values from the SYSENTER MSRs
    uint32_t sysenter_cs;
    uint64_t sysenter_esp;
    uint64_t sysenter_eip;

    if (ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &sysenter_cs))
        return X86EMUL_UNHANDLEABLE;
    if (ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &sysenter_esp))
        return X86EMUL_UNHANDLEABLE;
    if (ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &sysenter_eip))
        return X86EMUL_UNHANDLEABLE;

    // Set up segment registers for SYSENTER
    ctxt->regs->cs = sysenter_cs;
    ctxt->regs->ip = sysenter_eip;
    ctxt->regs->sp = sysenter_esp;

    // Update instruction pointer and stack pointer
    ctxt->sysenter_ip = (uintptr_t)ctxt->ops->get_instruction(ctxt);
    ctxt->regs->ip = ctxt->regs->ip;

    return X86EMUL_CONTINUE;
}

int emulate_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;
    uint32_t cs, eip, esp;

    if (ctxt->op_size == 2)
        return X86EMUL_UNSUPPORTED;

    if (ctxt->mode != X86EMUL_MODE_PROTECTED && ctxt->mode != X86EMUL_MODE_LONG)
        return X86EMUL_UNSUPPORTED;

    if (ctxt->rex_prefix & 0x8)
        return X86EMUL_UNSUPPORTED;

    if (ctxt->d & 2)
        return X86EMUL_UNSUPPORTED;

    if (ctxt->d & 1)
        return X86EMUL_UNSUPPORTED;

    if (ctxt->mode == X86EMUL_MODE_PROTECTED)
        return X86EMUL_UNSUPPORTED;

    if (ctxt->mode == X86EMUL_MODE_REAL)
        return X86EMUL_UNSUPPORTED;

    efer = ctxt->read_msr(ctxt, MSR_EFER);
    if (efer & EFER_LMA && ctxt->mode == X86EMUL_MODE_PROTECTED)
        return X86EMUL_UNSUPPORTED;

    if (ctxt->mode != X86EMUL_MODE_PROTECTED || (efer & EFER_LMA) == 0)
        return X86EMUL_UNSUPPORTED;

    cs = (ctxt->read_msr(ctxt, MSR_GS_BASE) >> 32) & 0xff;
    eip = (uint32_t)ctxt->read_msr(ctxt, MSR_GS_BASE);
    esp = (uint32_t)ctxt->read_msr(ctxt, MSR_GS_BASE);

    if ((cs & 0xf000) != 0x8) {
        return X86EMUL_UNSUPPORTED;
    }

    if ((eip & 0xffff0000) != 0x00000000) {
        return X86EMUL_UNSUPPORTED;
    }

    if (esp & 0xffff0000) {
        return X86EMUL_UNSUPPORTED;
    }

    ctxt->regs->eip = eip;
    ctxt->regs->esp = esp;
    ctxt->regs->cs = cs;
    return X86EMUL_CONTINUE;
}

int emulate_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;
    unsigned int mode;
    int rc;

    rc = ctxt->get_msr(ctxt, MSR_EFER, &efer);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    mode = (efer >> 12) & 0x3;
    if (mode == 0) {
        /* Real mode: inject general protection fault */
        return X86EMUL_UNHANDLEABLE;
    }

    if (mode == 1) {
        /* Compatibility mode: inject undefined instruction fault */
        return X86EMUL_UNHANDLEABLE;
    }

    /* Set up CS, DS, ES, and SS for the new mode */
    ctxt->src = (void *)&ctxt->sysenter_cs;
    rc = ctxt->read_register(ctxt, X86EMUL_REG_CS, ctxt->src);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = ctxt->get_msr(ctxt, MSR_GS_BASE, &ctxt->sysenter_gs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = ctxt->get_msr(ctxt, MSR_GS_BASE, &ctxt->sysenter_fs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = ctxt->get_msr(ctxt, MSR_LSTAR, &ctxt->sysenter_esp);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = ctxt->get_msr(ctxt, MSR_CSTAR, &ctxt->sysenter_eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    /* Update IP and SP */
    ctxt->eip = ctxt->sysenter_eip;
    ctxt->regs[VCPU_REGS_RSP] = ctxt->sysenter_esp;

    return X86EMUL_CONTINUE;
}

int x86emul_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;

    /* Get EFER MSR */
    if (ctxt->get_msr(ctxt, MSR_EFER, &efer))
        return X86EMUL_UNHANDLEDEXC;

    /* Check current mode */
    if ((ctxt->regs->cs & 3) == 1) {
        /* Real mode */
        return X86EMUL_GPFERR(0, 0);
    }

    if ((ctxt->regs->cs & 3) == 2) {
        /* Compatibility mode */
        return X86EMUL_UDFERR;
    }

    uint32_t sysenter_cs;
    uint64_t sysenter_esp;
    uint64_t sysenter_eip;

    if (ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &sysenter_cs))
        return X86EMUL_UNHANDLEDEXC;

    if (ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &sysenter_esp))
        return X86EMUL_UNHANDLEDEXC;

    if (ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &sysenter_eip))
        return X86EMUL_UNHANDLEDEXC;

    if ((sysenter_cs & 0xff00) == 0) {
        /* Invalid selector */
        return X86EMUL_GPFERR(0, 0);
    }

    /* Set up segment registers */
    ctxt->regs->cs = sysenter_cs & 0xffff;
    ctxt->regs->ip = sysenter_eip;
    ctxt->regs->sp = sysenter_esp;

    return X86EMUL_CONTINUE;
}

int do_sysenter(struct x86_emulate_ctxt *ctxt)
{
    unsigned long efer;
    unsigned long cs, eip, ss, esp;

    efer = get_msr(ctxt, MSR_EFER);

    if (ctxt->mode != X86EMUL_MODE_PROT) {
        return emulate_gp_fault(ctxt, 0);
    }

    if ((efer & EFER_LMA) && !(efer & EFER_SCE)) {
        return emulate_ud(ctxt);
    }

    if (ctxt->op_bytes != 2) {
        return emulate_ud(ctxt);
    }

    if (ctxt->regs->eflags & VM_MASK) {
        return emulate_gp_fault(ctxt, 0);
    }

    if (ctxt->regs->cs & 3) {
        return emulate_gp_fault(ctxt, 0);
    }

    if (ctxt->regs->cs != GDT_SELECTOR(GDT_CS)) {
        return emulate_gp_fault(ctxt, 0);
    }

    cs = get_msr(ctxt, MSR_GS_BASE);
    eip = get_msr(ctxt, MSR_GS_BASE + 4);
    ss = get_msr(ctxt, MSR_GS_BASE + 8);
    esp = get_msr(ctxt, MSR_GS_BASE + 12);

    ctxt->regs->cs = cs;
    ctxt->regs->eip = eip;
    ctxt->regs->ss = ss;
    ctxt->regs->esp = esp;

    return X86EMUL_CONTINUE;
}
